          ? null
          : (context) => prepareNextTurn?.call(context),
      toolMisuseBreaker: toolMisuseBreaker,
      getSteeringMessages: () async {
        if (skip) {
          skip = false;
          return const <Message>[];
        }
        final external =
            await externalSteeringSource?.call() ?? const <Message>[];
        return [...external, ..._steeringQueue.drain()];
