      _ => null,
    };
    if (persisted == null) {
      io.writeln('unknown scope: $scope (try global, project)');
      return;
    }
    if (!persisted) return;
    await _resolveSkillAvailability();
    _applyPromptComposition();
    io.writeln(
      'skills: ${enable ? 'enabled' : 'disabled'} ${skill.name} '
      '(scope: $scope)',
    );
  }

