  ) {
    final prompt = StringBuffer()
      ..write('<conversation>\n')
      ..write(conversation)
      ..write('\n</conversation>\n\n');
    if (candidates != null) {
      prompt
        ..write(candidates)
        ..write('\n\n');
    }
    if (pinnedOperative != null) {
      prompt
        ..write(pinnedOperative.block)
        ..write('\n\n');
    }
