  /// to the project scope; the settings-hub Skills flow routes here.
  Future<void> _skillsToggleSlash(bool enable, List<String> args) async {
    if (args.isEmpty) {
      io.writeln(
        'usage: /skills ${enable ? 'on' : 'off'} <name> [global|project]',
      );
      return;
    }
    await _applySkillToggle(
      enable,
      args.first,
